def set_zeroes(matrix):
    m, n = len(matrix), len(matrix[0])
    rows, cols = [False] * m, [False] * n
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                rows[i] = cols[j] = True
    for i in range(m):
        for j in range(n):
            if rows[i] or cols[j]:
                matrix[i][j] = 0

